def dedupe(xs):
    seen = set(); out = []
    for x in xs:
        if x not in seen:
            seen.add(x); out.append(x)
    return out

def is_pal(s):
    t = [c.lower() for c in s if c.isalnum()]
    return t == t[::-1]

def running_max(xs):
    out = []; m = None
    for x in xs:
        m = x if m is None or x > m else m
        out.append(m)
    return out

